// Regenerates packages/ink-io/src/tydro-registry.ts from the canonical Aave address book.
// Source: https://github.com/aave-dao/aave-address-book/blob/main/src/ts/AaveV3InkWhitelabel.ts
// Run: node scripts/sync-tydro-registry.mjs   (needs network access to raw.githubusercontent.com)
// Never hand-edit addresses in the generated file.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SRC = 'https://raw.githubusercontent.com/aave-dao/aave-address-book/main/src/ts/AaveV3InkWhitelabel.ts';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(root, 'packages/ink-io/src/tydro-registry.ts');

const res = await fetch(SRC);
if (!res.ok) throw new Error(`fetch ${SRC} → ${res.status}`);
const ts = await res.text();

const constant = (name) => {
  const m = ts.match(new RegExp(`export const ${name} = '(0x[0-9a-fA-F]{40})'`));
  if (!m) throw new Error(`missing ${name} in address book`);
  return m[1];
};
const chainId = Number(ts.match(/export const CHAIN_ID = (\d+)/)?.[1]);
if (chainId !== 57073) throw new Error(`address book CHAIN_ID ${chainId} ≠ 57073`);

const assetsBlock = ts.slice(ts.indexOf('export const ASSETS'), ts.indexOf('export const E_MODES'));
const assets = [];
for (const m of assetsBlock.matchAll(/^  (\w+): \{([\s\S]*?)^  \},/gm)) {
  const body = m[2];
  const get = (k) => body.match(new RegExp(`${k}: '(0x[0-9a-fA-F]{40})'`))?.[1];
  assets.push({
    symbol: m[1],
    decimals: Number(body.match(/decimals: (\d+)/)?.[1]),
    underlying: get('UNDERLYING'),
    aToken: get('A_TOKEN'),
    vToken: get('V_TOKEN'),
  });
}
if (assets.length === 0) throw new Error('parsed zero assets');

const today = new Date().toISOString().slice(0, 10);
const out = `// AUTOGENERATED by scripts/sync-tydro-registry.mjs on ${today}. DO NOT HAND-EDIT.
// Source: ${SRC}
// Tydro = Aave v3 white-label instance on Ink (chain ${chainId}).
import type { Address } from 'viem';

export const TYDRO_FETCHED = '${today}';
export const TYDRO_SOURCE = '${SRC}';

export const TYDRO = {
  POOL_ADDRESSES_PROVIDER: '${constant('POOL_ADDRESSES_PROVIDER')}',
  POOL: '${constant('POOL')}',
  ORACLE: '${constant('ORACLE')}',
  AAVE_PROTOCOL_DATA_PROVIDER: '${constant('AAVE_PROTOCOL_DATA_PROVIDER')}',
  UI_POOL_DATA_PROVIDER: '${constant('UI_POOL_DATA_PROVIDER')}',
  WALLET_BALANCE_PROVIDER: '${constant('WALLET_BALANCE_PROVIDER')}',
} as const satisfies Record<string, Address>;

export interface TydroReserve {
  symbol: string;
  decimals: number;
  underlying: Address;
  aToken: Address;
  vToken: Address;
}

export const TYDRO_RESERVES: readonly TydroReserve[] = [
${assets.map((a) => `  { symbol: '${a.symbol}', decimals: ${a.decimals}, underlying: '${a.underlying}', aToken: '${a.aToken}', vToken: '${a.vToken}' },`).join('\n')}
];
`;
writeFileSync(target, out);
console.log(`wrote ${target} with ${assets.length} reserves`);
